case "$(uname -s)" in
  Darwin*) os=macos ;;
  Linux*)  os=linux ;;
  CYGWIN*|MINGW*) os=windows ;;
  *) os=unknown ;;
esac

# Linux distro:
. /etc/os-release && echo "$ID $VERSION_ID"

(
  flock -n 9 || { echo 'already running'; exit 1; }
  # critical section
